// ❌ Violación de LSP — Square extiende Rectangle pero rompe su contrato
class Rectangle {
    int width, height;
    void setWidth(int w) { width = w; }
    void setHeight(int h) { height = h; }
    int area() { return width * height; }
}
class Square extends Rectangle {
    @Override void setWidth(int w) { width = height = w; } // rompe postcondición
    @Override void setHeight(int h) { width = height = h; }
}

